-- CRM Asesor – listas de precios del cotizador (una activa por vez)
-- Se cargan desde la página Precios subiendo el index.html del cotizador.
create table public.listas_precios (
  id uuid primary key default gen_random_uuid(),
  vigencia text not null,                 -- ej.: Octubre 2026
  precios jsonb not null,                 -- PRICES[zona].plans / directo / derivacion
  tope_aportes numeric not null,
  aumento numeric not null default 0,     -- % de aumento sobre la lista (como en el cotizador)
  activa boolean not null default false,
  creado_at timestamptz not null default now()
);
create unique index listas_precios_una_activa on public.listas_precios (activa) where activa;

alter table public.listas_precios enable row level security;
create policy "equipo gestiona listas_precios" on public.listas_precios for all to authenticated
  using (public.es_miembro()) with check (public.es_miembro());

-- Activa una lista y desactiva las demás en una sola operación
create or replace function public.activar_lista_precios(p_id uuid)
returns void language plpgsql security invoker set search_path = '' as $$
begin
  update public.listas_precios set activa = false where activa and id <> p_id;
  update public.listas_precios set activa = true where id = p_id;
end;
$$;

-- Cotización guardada en la ficha (campaña, modalidad, sueldos) para retomarla
alter table public.contactos add column cotizacion jsonb;

